#include "nano/core.hpp"
namespace nano {
static Rlp accesses(const std::vector<Access>& list){std::vector<Rlp> out;for(const auto& a:list){std::vector<Rlp> keys;for(const auto& key:a.keys){if(key.size()!=32)throw std::invalid_argument("access key length");keys.emplace_back(key);}out.emplace_back(std::vector<Rlp>{Rlp(unhex(address(a.address))),Rlp(keys)});}return Rlp(out);}
Rlp Transaction::payload() const {
 if(type>2)throw std::invalid_argument("unsupported transaction type");
 auto recipient=to?unhex(address(*to)):Bytes{};
 if(type==0)return Rlp(std::vector<Rlp>{Rlp(nonce),Rlp(gas_price),Rlp(gas),Rlp(recipient),Rlp(value),Rlp(data)});
 std::vector<Rlp> fields{Rlp(chain_id),Rlp(nonce)};
 if(type==2){fields.emplace_back(priority_fee);fields.emplace_back(max_fee);}else fields.emplace_back(gas_price);
 fields.emplace_back(gas);fields.emplace_back(recipient);fields.emplace_back(value);fields.emplace_back(data);fields.push_back(accesses(access_list));return Rlp(fields);
}
Bytes Transaction::signing_hash(bool protected_legacy) const {auto p=payload();if(type==0&&protected_legacy){p.items.emplace_back(chain_id);p.items.emplace_back(Int(0));p.items.emplace_back(Int(0));}auto encoded=p.encode();if(type)encoded.insert(encoded.begin(),uint8_t(type));return keccak(encoded);}
Int Transaction::intrinsic_gas() const {Int cost=21000;if(!to)cost+=32000;for(auto b:data)cost+=b?16:4;for(const auto& a:access_list)cost+=2400+1900*a.keys.size();return cost;}
Int Transaction::effective_gas_price(const Int& base) const {if(type!=2)return gas_price;return std::min(max_fee,Int(base+priority_fee));}
Json Transaction::to_json() const {Json j={{"type",quantity(Int(type))},{"nonce",quantity(nonce)},{"value",quantity(value)},{"chainId",quantity(chain_id)},{"gas",quantity(gas)},{"data",hex(data)},{"input",hex(data)}};j["to"]=to?Json(checksum_address(*to)):Json(nullptr);if(type==2){j["maxFeePerGas"]=quantity(max_fee);j["maxPriorityFeePerGas"]=quantity(priority_fee);}else j["gasPrice"]=quantity(gas_price);if(type){j["accessList"]=Json::array();for(const auto& a:access_list){Json keys=Json::array();for(const auto& k:a.keys)keys.push_back(hex(k));j["accessList"].push_back({{"address",checksum_address(a.address)},{"storageKeys",keys}});}}return j;}
Transaction Transaction::from_json(const Json& j){Transaction t;auto get=[&](const char* key,Int def){return j.contains(key)&&!j[key].is_null()?quantity(j[key]):def;};t.type=unsigned(u64(get("type",j.contains("maxFeePerGas")?Int(2):j.contains("accessList")?Int(1):Int(0))));t.nonce=get("nonce",0);t.value=get("value",0);t.chain_id=get("chainId",1337);t.gas=get("gas",21000);t.gas_price=get("gasPrice",1000000000);t.max_fee=get("maxFeePerGas",0);t.priority_fee=get("maxPriorityFeePerGas",0);if(j.contains("to")&&!j["to"].is_null()&&j["to"]!=""&&j["to"]!="0x")t.to=address(j["to"]);t.data=unhex(j.value("data",j.value("input",std::string("0x"))));if(j.contains("accessList"))for(const auto& a:j["accessList"]){Access item{address(a.at("address")),{}};for(const auto& k:a.at("storageKeys")){auto b=unhex(k);if(b.size()!=32)throw std::invalid_argument("access key length");item.keys.push_back(b);}t.access_list.push_back(item);}t.payload();return t;}
Bytes SignedTransaction::raw() const {auto p=tx.payload();p.items.emplace_back(v);p.items.emplace_back(r);p.items.emplace_back(s);auto result=p.encode();if(tx.type)result.insert(result.begin(),uint8_t(tx.type));return result;}
std::string SignedTransaction::sender() const {Int order("fffffffffffffffffffffffffffffffebaaedce6af48a03bbfd25e8cd0364141",16);if(s>order/2)throw std::invalid_argument("noncanonical high-s signature");unsigned rec;bool protect=true;if(tx.type){if(v<0||v>1)throw std::invalid_argument("invalid typed v");rec=unsigned(u64(v));}else if(v==27||v==28){rec=unsigned(u64(Int(v-27)));protect=false;}else if(v>=35){if((v-35)/2!=tx.chain_id)throw std::invalid_argument("chain id mismatch");rec=unsigned(u64(Int((v-35)%2)));}else throw std::invalid_argument("invalid legacy v");return public_address(recover_public_key(tx.signing_hash(protect),{rec,r,s}));}
Json SignedTransaction::to_json() const {auto j=tx.to_json();j["hash"]=hex(hash());j["from"]=sender();j["v"]=quantity(v);j["r"]=quantity(r);j["s"]=quantity(s);return j;}
SignedTransaction SignedTransaction::sign(Transaction tx,const Bytes& key){auto sig=sign_hash(key,tx.signing_hash());Int v=sig.v;if(tx.type==0)v+=tx.chain_id*2+35;return {std::move(tx),v,sig.r,sig.s};}
SignedTransaction SignedTransaction::decode(const Bytes& input){if(input.empty()||input.size()>1024*1024)throw std::invalid_argument("invalid transaction size");SignedTransaction st;auto& t=st.tx;Bytes encoded=input;if(input[0]<128){t.type=input[0];if(t.type<1||t.type>2)throw std::invalid_argument("unsupported transaction type");encoded.erase(encoded.begin());}auto p=Rlp::decode(encoded);size_t expected=t.type==0?9:t.type==1?11:12;if(!p.list||p.items.size()!=expected)throw std::invalid_argument("invalid transaction fields");size_t i=0;if(t.type)t.chain_id=p[i++].number();t.nonce=p[i++].number();if(t.type==2){t.priority_fee=p[i++].number();t.max_fee=p[i++].number();if(t.priority_fee>t.max_fee)throw std::invalid_argument("priority fee exceeds fee cap");}else t.gas_price=p[i++].number();t.gas=p[i++].number();auto recipient=p[i++].blob();if(!recipient.empty())t.to=address(hex(recipient));t.value=p[i++].number();t.data=p[i++].blob();if(t.type){auto list=p[i++];if(!list.list)throw std::invalid_argument("invalid access list");for(const auto& a:list.items){if(!a.list||a.items.size()!=2||!a[1].list)throw std::invalid_argument("invalid access entry");Access item{address(hex(a[0].blob())),{}};for(const auto& key:a[1].items){if(key.blob().size()!=32)throw std::invalid_argument("access key length");item.keys.push_back(key.blob());}t.access_list.push_back(item);}}
 st.v=p[i++].number();st.r=p[i++].number();st.s=p[i++].number();if(t.type==0)t.chain_id=st.v>=35?Int((st.v-35)/2):Int(0);st.sender();return st;
}
std::string create_address(const std::string& sender,const Int& nonce){auto hash=keccak(Rlp(std::vector<Rlp>{Rlp(unhex(address(sender))),Rlp(nonce)}).encode());return hex(Bytes(hash.begin()+12,hash.end()));}
std::string create2_address(const std::string& sender,const Bytes& salt,const Bytes& init_hash){if(salt.size()!=32||init_hash.size()!=32)throw std::invalid_argument("CREATE2 width");auto hash=keccak(concat(concat(concat(Bytes{255},unhex(address(sender))),salt),init_hash));return hex(Bytes(hash.begin()+12,hash.end()));}
}
